 protected readonly TabControl Pages=new NavigationTabs{Dock=DockStyle.Fill};protected readonly Dictionary<string,Control> Inputs=new Dictionary<string,Control>();protected bool Restoring;readonly string kind;internal string Kind{get{return kind;}}readonly CalculationReportView report=new CalculationReportView{Dock=DockStyle.Fill};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=40,Padding=new Padding(10)};
 protected DesignSheetForm(string title,string type){if(!ViewOnly.Opening&&!AccessCodes.CanUseApp(ProgramAccess.ForSheet(type)))throw new Exception("Design Sheets access required.");kind=type;RegisterDesignLoads();AppBrand.Apply(this);Text=title;ClientSize=new Size(1180,780);MinimumSize=new Size(820,600);Font=new Font("Segoe UI",9.25f);StartPosition=FormStartPosition.CenterParent;var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,MinimumSize=new Size(0,52),Padding=new Padding(8),WrapContents=true};Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=38};b.Click+=async(s,e)=>{try{if(text=="Calculate"||text=="Export report file"||text=="Print preview"||text=="Export PDF")await PrepareDocumentAsync();action();}catch(Exception ex){status.Text=ex.Message;status.ForeColor=Color.Firebrick;}};tools.Controls.Add(b);};/* one compact row (owner, 20 November 2026: "ang kalat"): Calculate, Print preview, Save, Open and the exports under Export */button("Calculate",Calculate);button("Print preview",()=>{using(var document=BuildDocument())CalculationReportView.ShowReport(this,document);});button("Save sheet XML",Save);button("Open sheet XML",Open);
