 /* Every design sheet page has the same two panes (owner, 20 November 2026: "lahat ganyan", "ayusin mo yung workspace ang gulo"):
    on the left a compact input form - one row per input, the label beside its box; on the right the section previews, tables
    and other wide blocks of that page, or, when the page has none, the calculation report kept up to date as the inputs change. */
 const int FormPane=540;
 protected FlowLayoutPanel Section(string title,string note){var page=new TabPage(title){BackColor=PaneBack};
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,BackColor=PaneBack,Padding=new Padding(12,12,12,8)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,FormPane));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));
  var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(14,10,14,14),Margin=new Padding(0,0,12,0),WrapContents=true,BackColor=Color.White};
  var wide=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(0),Margin=Padding.Empty,BackColor=PaneBack};
  var right=new Panel{Dock=DockStyle.Fill,Margin=Padding.Empty,BackColor=PaneBack};right.Controls.Add(wide);root.Controls.Add(flow,0,0);root.Controls.Add(right,1,0);flow.Tag=wide;page.Controls.Add(root);
  /* the explanation is shown by the window's info icon while this tab is open (owner, 20 November 2026) */InfoButton.Register(page,title,note);
  flow.Resize+=(sender,args)=>Arrange(flow);wide.Resize+=(sender,args)=>Arrange(flow);flow.ControlAdded+=(sender,args)=>{if(flow.IsHandleCreated)flow.BeginInvoke(new Action(()=>Arrange(flow)));};page.VisibleChanged+=(sender,args)=>{if(page.Visible){Arrange(flow);if(IsHandleCreated&&Visible)HookLive();LiveRefresh(page);}};
  var output=Pages.TabPages[Pages.TabPages.Count-1];Pages.TabPages.Remove(output);Pages.TabPages.Add(page);Pages.TabPages.Add(output);Pages.SelectedIndex=0;return flow;}
 /* a page that lays itself out takes its input flow back from the standard two panes */
 protected TabPage Detach(FlowLayoutPanel flow){var root=flow.Parent;var page=(TabPage)root.Parent;root.Controls.Remove(flow);page.Controls.Remove(root);root.Dispose();flow.Tag=null;flow.Visible=true;flow.Margin=Padding.Empty;return page;}
 internal static readonly Color PaneBack=Color.FromArgb(244,247,245);
 /* live calculation report for pages without wide blocks */
 readonly Dictionary<TabPage,CalculationReportView> liveViews=new Dictionary<TabPage,CalculationReportView>();readonly Timer liveTimer=new Timer{Interval=700};bool liveHooked;
 void LiveRefresh(TabPage page){if(Restoring||!liveHooked||!IsHandleCreated||!liveViews.ContainsKey(page)||!page.Visible)return;try{liveViews[page].SetDocument(BuildDocument());status.ForeColor=PowTheme.Teal;status.Text="Report updated from the inputs.";}catch(Exception ex){status.ForeColor=Color.Firebrick;status.Text=ex.Message;}}
 void HookLive(){if(liveHooked)return;liveHooked=true;liveTimer.Tick+=(s,e)=>{liveTimer.Stop();if(IsDisposed||Disposing||Pages.IsDisposed||Pages.TabCount==0)return;var page=Pages.SelectedTab;if(page!=null)LiveRefresh(page);};FormClosed+=(s,e)=>liveTimer.Dispose();Disposed+=(s,e)=>liveTimer.Dispose();
  EventHandler changed=(s,e)=>{if(Restoring)return;liveTimer.Stop();liveTimer.Start();};foreach(var c in Inputs.Values){c.TextChanged+=changed;var cb=c as CheckBox;if(cb!=null)cb.CheckedChanged+=changed;var co=c as ComboBox;if(co!=null)co.SelectedIndexChanged+=changed;}}
 /* the input pane narrows on a small window (360 to 540 px) so the drawings and models beside it keep room */
 static float Pane(Control root){int w=root.ClientSize.Width;return w<=0?FormPane:Math.Max(360,Math.Min(FormPane,(int)(w*.4)));}
 internal static void Arrange(FlowLayoutPanel flow){if(flow.IsDisposed||flow.FlowDirection!=FlowDirection.LeftToRight)return;var wide=flow.Tag as FlowLayoutPanel;
  /* wide blocks (previews, tables, action rows) go to the right pane in their order; headings stay with the inputs */
  if(wide!=null){var items=flow.Controls.Cast<Control>().ToList();Func<Control,bool> isWide=c=>Convert.ToString(c.Tag)=="FullWidth"&&!(c is Label);
   for(int k=0;k<items.Count;k++){var item=items[k];bool move=isWide(item)||(item is Label&&Convert.ToString(item.Tag)=="FullWidth"&&item.Name!="SectionNote"&&k+1<items.Count&&isWide(items[k+1]));/* a heading travels with the table under it */if(move){flow.Controls.Remove(item);wide.Controls.Add(item);}}}
  /* a page with nothing for the right pane uses the whole width for its inputs, in compact columns; the report has its own tab (owner,
     21 November 2026: "bat may calculation report, may separate tab naman for reports") */
  bool single=wide!=null&&wide.Controls.Count==0;{var root0=flow.Parent as TableLayoutPanel;if(root0!=null&&root0.ColumnStyles.Count>1&&flow.Controls.Count>0){float want=single?0:FormPane;var st=single?SizeType.Percent:SizeType.Absolute;if(root0.ColumnStyles[0].SizeType!=st||Math.Abs(root0.ColumnStyles[0].Width-(single?100:Pane(root0)))>.5f){root0.ColumnStyles[0].SizeType=st;root0.ColumnStyles[0].Width=single?100:Pane(root0);root0.ColumnStyles[1].SizeType=single?SizeType.Absolute:SizeType.Percent;root0.ColumnStyles[1].Width=single?0:100;}flow.Margin=single?Padding.Empty:new Padding(0,0,12,0);}}
  int full=flow.ClientSize.Width-flow.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-2;if(full<120)return;int colW=single?Math.Min(full,500):full,gap=28,cols=single?Math.Max(1,(full+gap)/(colW+gap)):1;int avail=colW;
  flow.SuspendLayout();try{Control previous=null;foreach(Control item in flow.Controls){string tag=Convert.ToString(item.Tag);bool field=tag=="DesignField";flow.SetFlowBreak(item,!(field&&cols>1));if(cols>1&&previous!=null&&!field)flow.SetFlowBreak(previous,true);previous=item;
   if(cols>1&&!field){item.Width=full;item.Margin=new Padding(0,item is Label?10:4,0,4);if(item.Name=="SectionNote")item.Height=TextRenderer.MeasureText(item.Text,item.Font,new Size(full,0),TextFormatFlags.WordBreak).Height+6;continue;}
   if(field){item.Width=avail;item.Margin=new Padding(0,0,0,2);var cap=item.Controls.OfType<Label>().FirstOrDefault();if(cap!=null){int lw=Math.Max(60,(int)(avail*.54)-8);int th=TextRenderer.MeasureText(cap.Text??"",cap.Font,new Size(lw,0),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height;item.Height=Math.Max(36,th+14);}if(cols>1)item.Margin=new Padding(0,0,gap,2);}
   else{item.Width=avail;item.Margin=new Padding(0,item is Label?10:4,0,4);if(item.Name=="SectionNote")item.Height=TextRenderer.MeasureText(item.Text,item.Font,new Size(avail,0),TextFormatFlags.WordBreak).Height+6;}}}
  finally{flow.ResumeLayout(true);}
  if(wide!=null){var root=flow.Parent as TableLayoutPanel;bool hasForm=flow.Controls.Count>0;if(root!=null&&root.ColumnStyles.Count>1&&!hasForm){if(Math.Abs(root.ColumnStyles[0].Width)>.5f)root.ColumnStyles[0].Width=0;flow.Visible=false;}
   var form=flow.FindForm() as DesignSheetForm;var page=flow.Parent==null?null:flow.Parent.Parent as TabPage;
   if(false&&wide.Controls.Count==0&&form!=null&&page!=null&&!form.liveViews.ContainsKey(page)){var view=new CalculationReportView{Dock=DockStyle.Fill};form.liveViews[page]=view;wide.Parent.Controls.Add(view);view.BringToFront();wide.Visible=false;if(form.liveHooked&&page.Visible)form.LiveRefresh(page);}
   int w=wide.ClientSize.Width-wide.Padding.Horizontal-(wide.VerticalScroll.Visible?SystemInformation.VerticalScrollBarWidth:0)-2;if(w>120){wide.SuspendLayout();try{foreach(Control item in wide.Controls){item.Width=w;item.Margin=new Padding(0,0,0,12);if(item.Name=="SectionNote")item.Height=TextRenderer.MeasureText(item.Text,item.Font,new Size(w,0),TextFormatFlags.WordBreak).Height+6;}}finally{wide.ResumeLayout(true);}}}}
 protected TextBox NumberField(FlowLayoutPanel panel,string key,string label,string value){var text=new TextBox{Text=value,Width=280};Field(panel,key,label,text);return text;}
 protected ComboBox Choice(FlowLayoutPanel panel,string key,string label,string[] values){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=280,DropDownWidth=500};combo.Items.AddRange(values);combo.AutoCompleteSource=AutoCompleteSource.ListItems;combo.AutoCompleteMode=AutoCompleteMode.SuggestAppend;if(values.Length>0)combo.SelectedIndex=0;Field(panel,key,label,combo);return combo;}
 protected CheckBox Toggle(FlowLayoutPanel panel,string key,string label,bool value){var check=new CheckBox{Text=label,Checked=value,Width=280,Height=40};Field(panel,key,"",check);return check;}
 protected void Field(FlowLayoutPanel panel,string key,string label,Control input){var box=new TableLayoutPanel{Width=420,Height=input is CheckBox?34:36,ColumnCount=2,RowCount=1,BackColor=Color.White,Margin=new Padding(0,0,0,2),Padding=Padding.Empty,Tag="DesignField"};box.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,54));box.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,46));box.RowStyles.Add(new RowStyle(SizeType.Percent,100));
  if(input is CheckBox){input.AutoSize=false;input.Dock=DockStyle.Fill;input.Margin=new Padding(0,4,0,0);box.Controls.Add(input,0,0);box.SetColumnSpan(input,2);}
  else{/* the whole caption is shown, wrapped onto a second line when long (owner, 20 November 2026: "di mabasa") */var caption=new Label{Text=label,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=false,UseMnemonic=false,Margin=new Padding(0,0,8,0),ForeColor=PowTheme.Ink};input.Anchor=AnchorStyles.Left|AnchorStyles.Right;input.Margin=new Padding(0,6,0,6);double numeric;if(input is TextBox&&double.TryParse(input.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out numeric))((TextBox)input).TextAlign=HorizontalAlignment.Right;box.Controls.Add(caption,0,0);box.Controls.Add(input,1,0);}
  panel.Controls.Add(box);Inputs.Add(key,input);}
 protected string Value(string key){return Inputs[key].Text.Trim();}protected double Number(string key){double value;if(!double.TryParse(Value(key),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new Exception("Check "+key+"; enter a finite number with a decimal point.");return value;}
 protected virtual EngineeringReport BuildEngineeringReport(){return ProfessionalReportExport.FromText(BuildReport());}
 protected virtual CalculationDocument BuildDocument(){return CalculationDocument.FromText(BuildReport());}
 protected void AddResultPage(TabPage page){var output=Pages.TabPages[Pages.TabPages.Count-1];Pages.TabPages.Remove(output);Pages.TabPages.Add(page);Pages.TabPages.Add(output);}
 // Lets a sheet finish asynchronous work (for example map tiles) before a report is built.
 protected virtual System.Threading.Tasks.Task PrepareDocumentAsync(){return System.Threading.Tasks.Task.FromResult(true);}
 protected virtual bool OptionalSavedInput(string key){return false;}/* inputs of older files that the sheet no longer has */protected virtual bool RetiredInput(string key){return false;}protected abstract string BuildReport();protected virtual void AfterRestore(){}
 /* a field the calculation does not use while a checkbox / choice says so is locked (greyed) (owner, 24 November 2026: "if naka check
    dapat di na pwede maginput, gawin din ito sa iba"); the rules run on every input change and after a sheet file is opened */
 readonly List<Action> enableRules=new List<Action>();bool enableHooked;
 protected void EnableWhen(Func<bool> condition,params string[] keys){enableRules.Add(()=>{bool on;try{on=condition();}catch(Exception){on=true;}foreach(var k in keys){Control c;if(Inputs.TryGetValue(k,out c)&&c.Enabled!=on)c.Enabled=on;}});
  if(!enableHooked){enableHooked=true;Shown+=(s,e)=>{foreach(var input in Inputs.Values){input.TextChanged+=(a,b)=>ApplyEnableRules();var check=input as CheckBox;if(check!=null)check.CheckedChanged+=(a,b)=>ApplyEnableRules();var combo=input as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(a,b)=>ApplyEnableRules();}ApplyEnableRules();};}}
 protected void ApplyEnableRules(){foreach(var rule in enableRules)rule();}
 protected bool On(string key){Control c;var check=Inputs.TryGetValue(key,out c)?c as CheckBox:null;return check!=null&&check.Checked;}protected virtual void WriteAdditionalState(XmlElement root){}protected virtual void ReadAdditionalState(XmlElement root){}
 public string CurrentReport(){return BuildReport();}
 void Calculate(){report.SetDocument(BuildDocument());status.ForeColor=PowTheme.Teal;status.Text="Calculated. Save sheet XML to keep inputs; exports contain the calculation report only.";Pages.SelectedIndex=Pages.TabCount-1;}
 void ExportExcel(){string text=BuildReport();using(var dialog=new SaveFileDialog{Filter="Excel workbook|*.xlsx",FileName=kind+"-Report.xlsx",OverwritePrompt=false})if(dialog.ShowDialog(this)==DialogResult.OK){using(var output=new ExcelLiveLink(dialog.FileName,true,false))output.UpdateDesignReport(kind,text);status.Text="Calculation report exported. Save sheet XML separately to retain editable inputs.";}}
 /* Ctrl+S saves to the file already chosen (Ctrl+Shift+S asks again), Ctrl+O opens (owner, 26 November 2026: "DI GUMAGANA ANG CTRL S");
    the five Design Loads sheets share one file */
 string sheetPath;static string designLoadsPath;
 string SavedPath{get{return DesignLoadsFile.Kinds.Contains(kind)?designLoadsPath:sheetPath;}set{if(DesignLoadsFile.Kinds.Contains(kind))designLoadsPath=value;else sheetPath=value;/* kept under the current project */ProjectFiles.Remember(DesignLoadsFile.Kinds.Contains(kind)?"design:loads":"design:"+kind,value);}}
 /* a file chosen elsewhere (the project's files from Project Information) */
 internal void OpenFile(string path){string xml=File.ReadAllText(path);SavedPath=path;if(DesignLoadsFile.Kinds.Contains(kind)){string msg=DesignLoadsFile.Open(xml,this);status.ForeColor=PowTheme.Teal;status.Text=msg;}else Restore(xml);}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==(Keys.Control|Keys.S)){Save(false);return true;}if(keyData==(Keys.Control|Keys.Shift|Keys.S)){Save(true);return true;}if(keyData==(Keys.Control|Keys.O)){Open();return true;}return base.ProcessCmdKey(ref msg,keyData);}
 void Save(){Save(false);}
 void Save(bool ask){bool loads=DesignLoadsFile.Kinds.Contains(kind);string path=SavedPath;if(ask||string.IsNullOrEmpty(path)){using(var dialog=new SaveFileDialog{Filter=loads?"DTCE Design Loads (all five sheets)|*.design.xml":"DTCE design sheet|*.design.xml",FileName=!string.IsNullOrEmpty(path)?Path.GetFileName(path):loads?"Design-Loads.design.xml":kind+".design.xml"}){if(!string.IsNullOrEmpty(path))try{dialog.InitialDirectory=Path.GetDirectoryName(path);}catch(Exception){}if(dialog.ShowDialog(this)!=DialogResult.OK)return;path=dialog.FileName;}}
  try{File.WriteAllText(path,loads?DesignLoadsFile.Bundle():Snapshot());SavedPath=path;status.ForeColor=PowTheme.Teal;status.Text=(loads?"Design Loads saved in one file ("+DesignLoadsFile.Count+" sheets): ":"Saved: ")+path+"  (Ctrl+S saves again)";}
  catch(Exception ex){status.ForeColor=Color.Firebrick;status.Text="Not saved: "+ex.Message;}}
 void Open(){using(var dialog=new OpenFileDialog{Filter="DTCE design sheet / Design Loads|*.design.xml"})if(dialog.ShowDialog(this)==DialogResult.OK){string xml=File.ReadAllText(dialog.FileName);SavedPath=dialog.FileName;
   if(DesignLoadsFile.Kinds.Contains(kind)){string msg=DesignLoadsFile.Open(xml,this);status.ForeColor=PowTheme.Teal;status.Text=msg;}else Restore(xml);}}
 /* Design Loads: the five sheets are saved and opened as one file (owner, 26 November 2026: "isang xml sheet na lang yung design loads") */
 /* one site location for every sheet with Latitude / Longitude (Wind, Earthquake; owner: "yung lat and long, bat paulit ulit pa din?"):
    typing it in one sheet fills the others, also sheets opened later (Links\site-link.xml) */
 static event Action<DesignSheetForm> SiteChanged;bool siteApplying,siteHooked;
 bool HasSite{get{return Inputs.ContainsKey("Latitude")&&Inputs.ContainsKey("Longitude");}}
 void HookSite(){if(!HasSite||siteHooked)return;siteHooked=true;foreach(var k in new[]{"Latitude","Longitude"})Inputs[k].TextChanged+=(s,e)=>{if(!Restoring&&!siteApplying)PublishSite();};
  Action<DesignSheetForm> h=f=>{if(f!=this&&!IsDisposed)ApplySite();};SiteChanged+=h;Disposed+=(s,e)=>SiteChanged-=h;ApplySite();}
 void PublishSite(){double la,lo;if(!double.TryParse(Value("Latitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out la)||!double.TryParse(Value("Longitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out lo))return;
  DesignLoadsLink.Set("site",new Dictionary<string,string>{{"lat",Value("Latitude")},{"lon",Value("Longitude")}});var ev=SiteChanged;if(ev!=null)ev(this);}
 internal void ApplySite(){var d=DesignLoadsLink.Get("site");string la,lo;if(d==null||!d.TryGetValue("lat",out la)||!d.TryGetValue("lon",out lo))return;if(Value("Latitude")==la&&Value("Longitude")==lo)return;
  siteApplying=true;try{Inputs["Latitude"].Text=la;Inputs["Longitude"].Text=lo;}finally{siteApplying=false;}}
 protected void RegisterDesignLoads(){if(!DesignLoadsFile.Kinds.Contains(kind))return;DesignLoadsFile.Register(this);Disposed+=(s,e)=>DesignLoadsFile.Unregister(this);Load+=(s,e)=>DesignLoadsFile.ApplyPending(this);}
 internal string Snapshot(){var doc=new XmlDocument();var root=doc.CreateElement("DesignSheet");root.SetAttribute("type",kind);root.SetAttribute("version","1");doc.AppendChild(root);foreach(var pair in Inputs){var field=doc.CreateElement("Input");field.SetAttribute("key",pair.Key);field.InnerText=pair.Value is CheckBox?((CheckBox)pair.Value).Checked.ToString():pair.Value.Text;root.AppendChild(field);}WriteAdditionalState(root);return doc.OuterXml;}
 internal void Restore(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=64000000}))doc.Load(reader);if(doc.DocumentElement.Name!="DesignSheet"||doc.DocumentElement.GetAttribute("type")!=kind||doc.DocumentElement.GetAttribute("version")!="1")throw new Exception("Choose a matching design-sheet file.");var values=new Dictionary<string,string>();foreach(XmlElement element in doc.DocumentElement.SelectNodes("Input")){string key=element.GetAttribute("key");if(RetiredInput(key)&&!Inputs.ContainsKey(key))continue;if(!Inputs.ContainsKey(key)||values.ContainsKey(key))throw new Exception("Invalid/duplicate design input.");values[key]=element.InnerText;}foreach(var pair in Inputs)if(!values.ContainsKey(pair.Key)){if(!OptionalSavedInput(pair.Key))throw new Exception("Incomplete design sheet.");values[pair.Key]=pair.Value is CheckBox?((CheckBox)pair.Value).Checked.ToString():pair.Value.Text;}foreach(var pair in values){var combo=Inputs[pair.Key] as ComboBox;if(combo!=null&&!combo.Items.Contains(pair.Value))throw new Exception("Saved profile or selection is unavailable: "+pair.Key);if(Inputs[pair.Key] is CheckBox)bool.Parse(pair.Value);}ReadAdditionalState(doc.DocumentElement);Restoring=true;try{foreach(var pair in values){var check=Inputs[pair.Key] as CheckBox;if(check!=null)check.Checked=bool.Parse(pair.Value);else Inputs[pair.Key].Text=pair.Value;}}finally{Restoring=false;}AfterRestore();if(HasSite)PublishSite();ApplyEnableRules();Calculate();}
}
class PurlinDesignForm:DesignSheetForm {
 /* wind loads linked from the Wind Load sheet's components and cladding (owner, 24 November 2026: "automatic link ng loads sa purlin
    design"): the chosen roof zone and the purlin's own effective wind area A = span x max(spacing, span / 3) give the wind pressure and
    suction (signed, normal to the roof); the two fields are locked while linked */
 static readonly string[] PurlinWindSources={"Typed values","Wind Load sheet: Components and Cladding - roof zone 1 (interior)","Wind Load sheet: Components and Cladding - roof zone 2 (edges)","Wind Load sheet: Components and Cladding - roof zone 3 (corners)"};
 Label windLinkInfo;bool windLinkHooked;
 int WindZone(){Control c;if(!Inputs.TryGetValue("WindSource",out c))return 0;return Math.Max(0,Array.IndexOf(PurlinWindSources,c.Text));}
 void ApplyWindLink(){if(windLinkInfo==null)return;int zone=WindZone();var pressure=Inputs["WindPressure"];var suction=Inputs["WindSuction"];
  if(zone==0){pressure.Enabled=true;suction.Enabled=true;windLinkInfo.ForeColor=PowTheme.Muted;windLinkInfo.Text="Typed wind values (signed, normal to the roof; suction negative). Choose a Wind Load sheet zone to link them.";return;}
  pressure.Enabled=false;suction.Enabled=false;var w=WindLink.Load();
  if(w==null){windLinkInfo.ForeColor=Color.Firebrick;windLinkInfo.Text="No Wind Load sheet results yet: open the Wind Load sheet, load the site, enable building pressures (C&C is calculated there), then come back.";return;}
  double span,spacing,area,gp,gn;if(!double.TryParse(Inputs["Span"].Text,NumberStyles.Float,CultureInfo.InvariantCulture,out span)||!double.TryParse(Inputs["Spacing"].Text,NumberStyles.Float,CultureInfo.InvariantCulture,out spacing)||span<=0||spacing<=0){windLinkInfo.ForeColor=Color.Firebrick;windLinkInfo.Text="Enter the purlin span and spacing to work out the linked wind loads.";return;}
  var p=WindLink.PurlinPressures(w,zone,span,spacing,out area,out gp,out gn);Func<double,string> inv=v=>v.ToString("0.###",CultureInfo.InvariantCulture);
  pressure.Text=inv(p[0]);suction.Text=inv(p[1]);double angle;double.TryParse(Inputs["Angle"].Text,NumberStyles.Float,CultureInfo.InvariantCulture,out angle);
  windLinkInfo.ForeColor=Math.Abs(angle-w.Angle)>1?Color.Firebrick:PowTheme.Teal;
  windLinkInfo.Text="Linked to the Wind Load sheet ("+w.Saved.ToString("dd MMM HH:mm",CultureInfo.InvariantCulture)+", "+w.Site+"): qh = "+inv(w.Qh)+" kPa (exposure "+w.Exposure+", wind from "+w.Direction+"), GCpi ±"+inv(w.GCpi)+". A = "+inv(span)+" × max("+inv(spacing)+", "+inv(span/3)+") = "+inv(area)+" m², GCp +"+inv(gp)+" / "+inv(gn)+" → p = "+inv(p[0])+" / "+inv(p[1])+" kPa."+(Math.Abs(angle-w.Angle)>1?" Roof angle here "+inv(angle)+"° differs from the wind sheet's "+inv(w.Angle)+"°.":"");}
 protected override void OnShown(EventArgs e){base.OnShown(e);if(!windLinkHooked&&windLinkInfo!=null){windLinkHooked=true;var src=(ComboBox)Inputs["WindSource"];src.SelectedIndexChanged+=(s,a)=>ApplyWindLink();Inputs["Span"].TextChanged+=(s,a)=>{if(WindZone()>0)ApplyWindLink();};Inputs["Spacing"].TextChanged+=(s,a)=>{if(WindZone()>0)ApplyWindLink();};Inputs["Angle"].TextChanged+=(s,a)=>{if(WindZone()>0)ApplyWindLink();};Activated+=(s,a)=>{if(WindZone()>0)ApplyWindLink();};}ApplyWindLink();}

 /* owner (20 November 2026): "alisin na yung section properties sa purlin design na tab, icompute na lang internally",
    "masmagandang workspace", "di nakakaprofessional tignan, ang kalat pa": one clean page - a compact input form on the left
    (label and unit beside each input, in four groups), and on the right the section, its computed properties and the results of
    the workbook checks, recalculated as the inputs change. The full calculation stays in the Calculation report tab. */
 static readonly Color Back=Color.FromArgb(242,244,246),Card=Color.White,Line=Color.FromArgb(222,227,232),Pass=Color.FromArgb(28,122,84),Fail=Color.FromArgb(190,45,45);
 readonly ComboBox profiles;readonly Label verdict=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI Semibold",12f),UseMnemonic=false,Padding=new Padding(14,0,0,0)};
 readonly Label verdictNote=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,ForeColor=PowTheme.Muted,UseMnemonic=false,Padding=new Padding(0,0,14,0)};
 readonly SummaryTable props=Table(new[]{"Property","Value"}),checks=Table(new[]{"Check","Actual","Allowed","Ratio","Result"});readonly Timer live=new Timer{Interval=350};
 public PurlinDesignForm():base("Purlin Design | Workbook ASD checks","Purlin-Design"){
  var flow=Section("Purlin design","Based on PS Design of Purlin.xlsm. Signed wind normal to roof; negative values represent uplift/suction. This sheet evaluates the listed workbook flexure/deflection checks, not the complete cold-formed member design.\r\n\r\nSection properties are computed from the standard section dimensions (the catalogue gives dimensions and mass only): nonoverlapping rectangular plates, bend radii neglected; Ixy is kept for Z shapes. Additional buckling, shear and connection checks remain outside this sheet.");
  var page=(TabPage)flow.Parent.Parent;var oldRoot=flow.Parent;page.Controls.Clear();oldRoot.Dispose();page.BackColor=Back;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(14),BackColor=Back};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,410));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));
  /* inputs */
  var left=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Back,Padding=new Padding(0,0,12,0)};var form=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,ColumnCount=2,BackColor=Card,Padding=new Padding(16,6,16,14)};form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,52));form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,48));Border(form);left.Controls.Add(form);
  Heading(form,"Member");Text(form,"Name","Name","Purlin");profiles=Pick(form,"Profile","Profile",SteelCatalog.Profiles.Where(p=>p.Kind=="Purlin").Select(p=>p.Name).ToArray());
  Heading(form,"Geometry");Pick(form,"Support","Support",new[]{"Simply supported","Cantilever"});Text(form,"Span","Span / cantilever (m)","5");Text(form,"Spacing","Purlin spacing (m)","0.4");Text(form,"Angle","Roof angle (deg)","13");Pick(form,"SagRods","Effective sag rods",new[]{"0","1","2"});Pick(form,"Ceiling","Ceiling",new[]{"Not supporting ceiling","Supporting nonplaster ceiling","Supporting plaster ceiling"});
  Heading(form,"Loads");Text(form,"Dead","Superimposed dead (kPa)","0.35");Text(form,"Live","Roof live (kPa)","1");Pick(form,"WindSource","Wind loads from",PurlinWindSources);Text(form,"WindPressure","Wind pressure (kPa)","0");Text(form,"WindSuction","Wind suction (kPa)","0");windLinkInfo=new Label{AutoSize=false,Width=360,Height=78,ForeColor=PowTheme.Muted,Margin=new Padding(0,2,0,6)};form.Controls.Add(windLinkInfo);form.SetColumnSpan(windLinkInfo,2);
  Heading(form,"Material");Text(form,"Fy","Yield strength Fy (MPa)","248");Text(form,"E","Modulus E (MPa)","200000");var inc=new CheckBox{Text="Alternate 4/3 allowable increase (workbook)",Checked=true,AutoSize=true,Margin=new Padding(0,8,0,2)};form.Controls.Add(inc);form.SetColumnSpan(inc,2);Inputs.Add("AlternateIncrease",inc);
  /* section, properties and results */
  var right=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=3,BackColor=Back,Padding=Padding.Empty};right.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,62));right.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));right.RowStyles.Add(new RowStyle(SizeType.Absolute,52));right.RowStyles.Add(new RowStyle(SizeType.Percent,55));right.RowStyles.Add(new RowStyle(SizeType.Percent,45));
  var band=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,BackColor=Card,Margin=new Padding(0,0,0,10)};band.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,55));band.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));band.Controls.Add(verdict,0,0);band.Controls.Add(verdictNote,1,0);Border(band);right.Controls.Add(band,0,0);right.SetColumnSpan(band,2);
  var preview=new SteelSectionPreview(()=>SteelCatalog.Find(profiles.Text),()=>false,profiles){Dock=DockStyle.Fill,Tag=null};right.Controls.Add(CardOf("Section",preview,new Padding(0,0,10,10)),0,1);right.Controls.Add(CardOf("Computed section properties",props,new Padding(0,0,0,10)),1,1);
  var results=CardOf("Workbook checks (ASD flexure and deflection)",checks,Padding.Empty);right.Controls.Add(results,0,2);right.SetColumnSpan(results,2);
  root.Controls.Add(left,0,0);root.Controls.Add(right,1,0);page.Controls.Add(root);
  live.Tick+=(s,e)=>{live.Stop();Evaluate();};FormClosed+=(s,e)=>live.Dispose();foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>Changed();var cb=c as CheckBox;if(cb!=null)cb.CheckedChanged+=(s,e)=>Changed();var co=c as ComboBox;if(co!=null)co.SelectedIndexChanged+=(s,e)=>Changed();}
  Evaluate();
 }
 void Changed(){if(Restoring)return;live.Stop();live.Start();}
 static void Border(Control c){c.Paint+=(s,e)=>{using(var p=new Pen(Line))e.Graphics.DrawRectangle(p,0,0,c.Width-1,c.Height-1);};}
 static SummaryTable Table(string[] heads){var t=new SummaryTable{Columns=heads,Weights=heads.Length>2?new[]{3.2f,1.3f,1.3f,.9f,.8f}:new[]{1f,1.4f}};return t;}
 static Panel CardOf(string title,Control body,Padding margin){var card=new Panel{Dock=DockStyle.Fill,BackColor=Card,Padding=new Padding(14,40,14,12),Margin=margin};Border(card);card.Paint+=(s,e)=>{using(var f=new Font("Segoe UI Semibold",10f))using(var b=new SolidBrush(PowTheme.Ink))e.Graphics.DrawString(title,f,b,12,12);};body.Dock=DockStyle.Fill;card.Controls.Add(body);return card;}
 static void Heading(TableLayoutPanel form,string text){var l=new Label{Text=text.ToUpperInvariant(),AutoSize=true,Font=new Font("Segoe UI Semibold",8.5f),ForeColor=PowTheme.Teal,Margin=new Padding(0,14,0,4),UseMnemonic=false};form.Controls.Add(l);form.SetColumnSpan(l,2);}
 void Row(TableLayoutPanel form,string key,string label,Control input){var l=new Label{Text=label,AutoSize=false,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=PowTheme.Ink,Margin=new Padding(0,3,8,3),UseMnemonic=false,Height=30};input.Dock=DockStyle.Fill;input.Margin=new Padding(0,3,0,3);form.Controls.Add(l);form.Controls.Add(input);Inputs.Add(key,input);}
 void Text(TableLayoutPanel form,string key,string label,string value){Row(form,key,label,new TextBox{Text=value,BorderStyle=BorderStyle.FixedSingle,TextAlign=HorizontalAlignment.Right});}
 ComboBox Pick(TableLayoutPanel form,string key,string label,string[] values){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,DropDownWidth=320,FlatStyle=FlatStyle.Flat};c.Items.AddRange(values);if(values.Length>0)c.SelectedIndex=0;Row(form,key,label,c);return c;}
 PurlinDesignInput Input(){var profile=SteelCatalog.Find(Value("Profile"));var p=PurlinProperties.Calculate(profile);return new PurlinDesignInput{Name=Value("Name"),Profile=profile,Properties=p,Support=Value("Support"),Span=Number("Span"),Spacing=Number("Spacing"),Angle=Number("Angle"),SagRods=int.Parse(Value("SagRods")),Ceiling=Value("Ceiling"),Dead=Number("Dead"),Live=Number("Live"),WindPressure=Number("WindPressure"),WindSuction=Number("WindSuction"),Fy=Number("Fy"),E=Number("E"),AlternateIncrease=((CheckBox)Inputs["AlternateIncrease"]).Checked};}
 void Evaluate(){Func<double,string> f=v=>v.ToString("#,##0.##",CultureInfo.InvariantCulture);
  try{var p=PurlinProperties.Calculate(SteelCatalog.Find(profiles.Text));props.Clear();foreach(var row in new[]{new[]{"Area A",f(p.Area)+" mm²"},new[]{"Ix",f(p.Ix)+" mm⁴"},new[]{"Iy",f(p.Iy)+" mm⁴"},new[]{"Ixy",f(p.Ixy)+" mm⁴"},new[]{"Sx",f(p.Sx)+" mm³"},new[]{"Sy",f(p.Sy)+" mm³"}})props.Add(row);}catch(Exception ex){props.Clear();props.Add(new[]{"Section",ex.Message});}
  checks.Clear();
  try{var input=Input();var r=PurlinDesigner.Calculate(input);Action<string,string,string,double> add=(name,actual,allowed,ratio)=>checks.Add(new[]{name,actual,allowed,ratio.ToString("0.00",CultureInfo.InvariantCulture),ratio<=1?"OK":"NG"},ratio<=1?Pass:Fail);
   add("Combined flexure, basic allowable","","",r.Basic);add("Combined flexure, alternate allowable"+(input.AlternateIncrease?" (4/3)":""),"","",r.Alternate);
   add("Live load deflection",f(r.LiveDeflection)+" mm",f(r.LiveLimit)+" mm",r.LiveLimit>0?r.LiveDeflection/r.LiveLimit:0);add("Dead + live deflection",f(r.TotalDeflection)+" mm",f(r.TotalLimit)+" mm",r.TotalLimit>0?r.TotalDeflection/r.TotalLimit:0);
   double worst=new[]{r.Basic,r.Alternate,r.LiveLimit>0?r.LiveDeflection/r.LiveLimit:0,r.TotalLimit>0?r.TotalDeflection/r.TotalLimit:0}.Max();bool ok=r.WithinWorkbookChecks;
   verdict.Text=(ok?"✓  Passes the workbook checks":"✕  Does not pass the workbook checks");verdict.ForeColor=ok?Pass:Fail;verdictNote.Text=input.Profile.Name+"  ·  "+input.Support.ToLowerInvariant()+", "+f(input.Span)+" m  ·  governing ratio "+worst.ToString("0.00",CultureInfo.InvariantCulture);}
  catch(Exception ex){verdict.Text="Enter the inputs";verdict.ForeColor=PowTheme.Muted;verdictNote.Text=ex.Message;}}
 protected override void AfterRestore(){ApplyWindLink();Evaluate();}
 /* files saved before v6.0.13 kept a Section properties tab */
 protected override bool RetiredInput(string key){return new[]{"Verified","Ix","Iy","Ixy","Sx","Sy"}.Contains(key);}
 protected override string BuildReport(){var input=Input();return PurlinDesigner.Report(input,PurlinDesigner.Calculate(input));}
 /* the illustrated report: section, load resolution, moment diagrams, utilisation, then the complete calculation */
 protected override CalculationDocument BuildDocument(){var input=Input();return PurlinReport.Build(input,PurlinDesigner.Calculate(input));}
}
}

namespace BeamScheduleFormatter {
/* a small read-only table drawn by hand (results and properties summaries of the design sheets): header in muted capitals,
   hairline row dividers, numbers right-aligned, the last column may carry a status colour */
sealed class SummaryTable:Control {
 public string[] Columns=new string[0];public float[] Weights;readonly System.Collections.Generic.List<string[]> rows=new System.Collections.Generic.List<string[]>();readonly System.Collections.Generic.List<Color> status=new System.Collections.Generic.List<Color>();
 public SummaryTable(){DoubleBuffered=true;ResizeRedraw=true;BackColor=Color.White;Font=new Font("Segoe UI",9.5f);}
 public void Clear(){rows.Clear();status.Clear();Invalidate();}
 public void Add(string[] row,Color? last=null){rows.Add(row);status.Add(last??Color.Empty);Invalidate();}
 internal int Count{get{return rows.Count;}}internal string Cell(int r,int c){return rows[r][c];}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;int n=Columns.Length;if(n==0)return;var w=Weights??Enumerable.Repeat(1f,n).ToArray();float total=w.Sum();float[] xs=new float[n+1];for(int i=0;i<n;i++)xs[i+1]=xs[i]+Width*w[i]/total;
  int rowH=Math.Max(26,Font.Height+12),y=0;using(var head=new Font("Segoe UI Semibold",8.5f))using(var bold=new Font(Font,FontStyle.Bold))using(var line=new Pen(Color.FromArgb(226,230,235))){
   for(int i=0;i<n;i++)TextRenderer.DrawText(g,Columns[i].ToUpperInvariant(),head,new Rectangle((int)xs[i]+6,y,(int)(xs[i+1]-xs[i])-12,rowH),PowTheme.Muted,(i>0&&n>2&&i<n-1?TextFormatFlags.Right:TextFormatFlags.Left)|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);
   y+=rowH;g.DrawLine(line,0,y-1,Width,y-1);
   for(int r=0;r<rows.Count;r++){for(int i=0;i<n&&i<rows[r].Length;i++){bool st=i==n-1&&status[r]!=Color.Empty;TextRenderer.DrawText(g,rows[r][i]??"",st?bold:Font,new Rectangle((int)xs[i]+6,y,(int)(xs[i+1]-xs[i])-12,rowH),st?status[r]:PowTheme.Ink,(i>0&&n>2&&i<n-1?TextFormatFlags.Right:TextFormatFlags.Left)|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
    y+=rowH;g.DrawLine(line,0,y-1,Width,y-1);}}}
}
}
